"""Render an existing dry-run bundle as a read-only, self-contained approval report."""
import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("review", type=Path)
parser.add_argument("output", type=Path)
parser.add_argument("--label", default="CONTENT-06")
args = parser.parse_args()
bundle = json.loads(args.review.read_text(encoding="utf-8"))
assert bundle["human_approvals"] == 0 and bundle["execute"] is False
payload = json.dumps(bundle, ensure_ascii=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
page = r'''<!doctype html><html lang="ru"><meta charset="utf-8"><title>CONTENT-06 · решения по партии SRD 2024</title>
<meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root{color-scheme:dark;font:15px/1.5 system-ui;background:#13171d;color:#e2e5eb}body{margin:0}header,main,footer{padding:22px 28px}header{border-bottom:1px solid #39414e}h1{font-size:25px;margin:0 0 12px}h2{font-size:19px}p{max-width:1100px}small,.muted{color:#aab4c4}.stats{display:flex;gap:10px;flex-wrap:wrap}.stats span{padding:8px 14px;border:1px solid #445062;border-radius:8px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px}input,select,button{font:inherit;color:inherit;background:#202833;border:1px solid #536279;padding:9px;border-radius:6px}input{min-width:260px;flex:1}button{cursor:pointer}.layout{display:grid;grid-template-columns:minmax(460px,1fr) minmax(400px,1.1fr);gap:24px}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{overflow-wrap:anywhere}.controls>*{max-width:100%;box-sizing:border-box}select{min-width:0}button{max-width:100%;text-align:left}td,th{padding:9px 7px;border-bottom:1px solid #343e4b;text-align:left;vertical-align:top}th{position:sticky;top:0;background:#13171d}.list{max-height:77vh;overflow:auto}tr.selected{background:#2a3c4c}aside{max-height:77vh;overflow:auto;padding:0 12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1c232d;padding:14px;border-radius:8px;font-size:12px}.prose{white-space:pre-wrap;overflow-wrap:anywhere}details{margin:12px 0}summary{cursor:pointer;color:#c4d5e9}code{overflow-wrap:anywhere}textarea{box-sizing:border-box;width:100%;min-height:120px;background:#1c232d;color:inherit;padding:12px}footer{border-top:1px solid #39414e;font-size:12px}@media(max-width:960px){.layout{display:block}.list,aside{max-height:none}header,main,footer{padding:16px}input{min-width:160px}}
</style><header><h1>CONTENT-06 · решения по партии SRD 2024</h1>
<p>Это результаты автопроверок, <strong>а не одобрение семантики</strong>. У всех записей решение человека ожидается, execute=false. Отчёт не импортирует данные и не меняет manifest. Кандидатам нужна вычитка EN/RU и проекции; спорные записи разбираются отдельно.</p><div class="stats" id="stats"></div><details><summary>Границы проверки и подпись пакета</summary><p>Проверены исходные идентификаторы, checksum, проекция v4, типы/диапазоны характеристик, языковые признаки и числовые токены, live baseline и структурная совместимость справочной копии. Числовая эвристика не доказывает полноту/точность перевода. Редакция 2024 проверена; точная ревизия 5.2.1 всего upstream не подтверждена. Artwork не подключается.</p><code id="checksum"></code></details></header>
<main><div class="controls"><input id="search" aria-label="Поиск EN RU ID" placeholder="Поиск EN / RU / ID"><select id="status" aria-label="Статус"><option value="">Все статусы</option><option value="validated_candidate">Кандидаты после автопроверок</option><option value="manual_review">Нужно ручное ревью</option><option value="rejected">Отклонены до исправления</option></select><select id="group" aria-label="Группа"><option value="">Все группы</option></select></div><p id="count" class="muted"></p>
<div class="layout"><div class="list"><table><thead><tr><th>Запись</th><th>Решение</th><th>Причины</th></tr></thead><tbody id="rows"></tbody></table></div><aside id="detail" aria-label="Тексты и точный diff"><p>Выберите запись для EN/RU, характеристик и точного before/after.</p></aside></div>
<details><summary>Короткая форма группового решения</summary><p>Это только текст для ручного ответа. Удалите группы, которые не прочитаны/не одобрены. B-baseline принимается отдельно и только для перечисленных ID/digest.</p><textarea id="decision" readonly aria-label="Шаблон решения"></textarea></details></main>
<footer>Источник — закреплённый Unified export SRD 2024; исходные тексты и upstream review flags сохранены. This work includes material from the System Reference Document 5.2.1 by Wizards of the Coast LLC, available at <a href="https://www.dndbeyond.com/srd">the official SRD page</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/legalcode">CC BY 4.0</a>. Русский текст не является официальной локализацией.</footer>
<script type="application/json" id="data">__PAYLOAD__</script><script>
const b=JSON.parse(document.getElementById('data').textContent),inventory=new Map(b.inventory.map(x=>[x.id,x]));
const labels={validated_candidate:'Кандидат · смысл не одобрен',manual_review:'Ручное ревью',rejected:'Отложить до исправления'};
const reasons={adapter_validation_failed:'Источник отклонён адаптером',unrecognized_or_modified_live_baseline:'Текущий baseline не признан: не перезаписывать',consumer_rarity_would_fall_back_to_common:'Копия потеряет редкость и станет common',en_ru_numeric_tokens_differ:'Числа EN/RU различаются: сверить полный текст',one_language_description_missing:'Нет описания на одном языке',required_prose_missing:'Нет необходимого текста',ru_name_missing:'Нет RU-имени',ru_text_without_cyrillic:'RU без кириллицы',official_reference_missing:'Нет справочного официального evidence',higher_level_not_explicit_in_both_full_texts:'Усиление не показано явно в обоих полных текстах',manual_spell_structured_damage_requires_semantic_review:'Структурированный damage требует проверки смысла',magic_variant_variable_or_unsupported_rarity:'Вариант/переменная/неподдержанная редкость',curated_description_differs_from_raw:'Редакторский текст отличается от raw',reference_ability_validation_failed:'Справочная Ability не прошла YTT validator',reference_item_validation_failed:'Справочный Item не прошёл validator'};
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n},get=id=>document.getElementById(id),reason=x=>reasons[x]||(x.startsWith('mechanics_differs_from_raw:')?'Характеристика отличается от raw: '+x.split(':')[1]:x);
for(const [key,value] of Object.entries(b.counts))get('stats').append(el('span',labels[key]+': '+value));get('stats').append(el('span','Одобрений: 0 · execute=false'));get('checksum').textContent='bundle_checksum: '+b.bundle_checksum;
for(const [key,ids] of Object.entries(b.groups)){const o=el('option',key+' · '+ids.length);o.value=key;get('group').append(o)}
let chosen;
function section(parent,title,value){const d=el('details'),s=el('summary',title);d.append(s,el('pre',typeof value==='string'?value:JSON.stringify(value,null,2)));parent.append(d)}
function inspect(r){chosen=r.id;const p=r.plan,q=r.quality,n=p.normalized||{},names=inventory.get(r.id)||{},a=get('detail');a.replaceChildren(el('h2',names.name_ru||names.name_en||r.id),el('p',r.id),el('p',labels[q.status]+' · '+(p.errors?'не сравнивалось: ошибка источника':p.action)+' · execute=false'));
const all=[...q.hard_errors,...q.attention];if(all.length)a.append(el('p',all.map(reason).join(' • ')));a.append(el('p',q.status==='rejected'?'По умолчанию: исключить до исправления.':q.status==='manual_review'?'По умолчанию: отложить до адресной вычитки/исправления.':'Предложение: утвердить группу только после вычитки EN/RU/проекции; не применять автоматически.'));
for(const lang of ['en','ru']){const text=n.content?.languages?.[lang]||r.source_evidence?.languages?.[lang];a.append(el('h3',lang.toUpperCase()+' · '+(text?.name||names['name_'+lang]||'нет имени')));const desc=Array.isArray(text?.description)?text.description.join('\n\n'):text?.description;const para=el('p',desc||(p.errors?'Адаптер отклонил источник; проекция не подготовлена.':'Описание отсутствует в источнике; ничего не добавлено.'));para.className='prose';a.append(para)}
section(a,'Результаты автопроверок и ошибки',q);section(a,'Исходные характеристики · raw / curated / provenance',r.source_evidence);section(a,'Технические исправления нормализации',n.content?.normalization_repairs||{});if(r.prior_screening)section(a,'Переиспользованное CONTENT-06 ревью',r.prior_screening);if(r.baseline_proposal)section(a,'Отдельное B-предложение · НЕ подтверждено',r.baseline_proposal);section(a,'Хеши и идентичность',{entry_id:p.existing_entry_id,source_checksum:p.source_checksum,content_checksum:p.checksum,projection_checksum_v4:p.projection_checksum,baseline:p.baseline});section(a,'Структурированные поля · proposed',Object.fromEntries(Object.entries(n).filter(([key])=>key!=='content'&&key!=='description')));section(a,'Точный diff нормализации · before / after',p.content_diff?.projection||p.errors);section(a,'Точный diff языка / provenance / review',p.content_diff||p.errors);section(a,'Все изменяемые поля Entry',p.diff||p.errors);render()}
function render(){const query=get('search').value.toLocaleLowerCase(),status=get('status').value,group=get('group').value;let count=0;get('rows').replaceChildren();for(const r of b.records){const n=inventory.get(r.id)||{};if(status&&r.quality.status!==status||group&&r.group!==group||query&&!((n.name_en||'')+' '+(n.name_ru||'')+' '+r.id).toLocaleLowerCase().includes(query))continue;count++;const tr=el('tr');if(chosen===r.id)tr.className='selected';const td=el('td'),button=el('button',n.name_en||r.id);button.onclick=()=>inspect(r);td.append(button,el('div',n.name_ru||''),el('small',r.kind==='magic_item'?(r.plan.normalized?.rarity||r.stratum):r.stratum));tr.append(td,el('td',labels[r.quality.status]+' / '+(r.plan.errors?'invalid':r.plan.action)),el('td',[...r.quality.hard_errors,...r.quality.attention].map(reason).join('; ')||'Нет дополнительных машинных замечаний; семантика ожидает человека'));get('rows').append(tr)}get('count').textContent='Показано '+count+' из '+b.selected+'. Группы точные; исключённые/спорные строки не одобряются групповым подтверждением.'}
for(const id of ['search','status','group'])get(id).oninput=render;
get('decision').value='CONTENT-06; bundle '+b.bundle_checksum+'\nПроверяющий/время: ____\nEN/RU и проекции прочитаны. Одобряю только группы: ____\nbrowse=true, copy=true, execute=false.\nОтдельно принимаю legacy-equipment-missing-null-ammunition-v1 для точных ID/digest выбранных групп: ДА / НЕТ.\nОстальные manual_review/rejected: отложить.\nФактический импорт этим решением не разрешаю.';
try{const initial=decodeURIComponent(location.hash.slice(1));if(b.groups[initial])get('group').value=initial}catch{}
render();
</script></html>'''
if bundle["adapter_version"] >= 5:
    page = page.replace("legacy-equipment-missing-null-ammunition-v1", "все перечисленные policy/ID/digest")
with args.output.open("x", encoding="utf-8", newline="\n") as stream:
    stream.write(page.replace("CONTENT-06", args.label).replace("проекция v4", "проекция v" + str(bundle["adapter_version"])).replace("projection_checksum_v4", "projection_checksum").replace("__PAYLOAD__", payload))
print(f"Read-only approval report: {args.output}")
